INSERT INTO menu_item (id, category_id, name, description, price, image_url, is_soup_base, track_inventory, is_refill, suitable_for, spicy_level, is_vegetarian, contains_beef, sold_out, sort_order, active) VALUES
  (1, 1, '招牌麻辣鍋底', '牛油與 18 種辛香料慢炒，附鴨血豆腐。', 480, NULL, 1, 1, 0, 'ALL', 2, 0, 1, 0, 1, 1),
  (2, 1, '酸菜白肉鍋底', '自家醃漬兩週的酸白菜，湯頭酸香不嗆。', 420, NULL, 1, 1, 0, 'ALL', 0, 0, 0, 0, 2, 1),
  (3, 1, '昆布鍋底', '北海道昆布熬底，清甜好入口，素食可點。', 380, NULL, 1, 1, 0, 'ALL', 0, 1, 0, 0, 3, 1),
  (4, 1, '鴛鴦鍋底', '左右各選一種湯底，價格依所選湯底計算。', 0, NULL, 1, 1, 0, 'ALL', 0, 0, 0, 0, 4, 1),
  (5, 2, '安格斯霜降牛五花', '厚切 3mm，涮 8 秒最好吃。油花分布均勻，是我們賣最好的一款。', 380, NULL, 0, 1, 0, 'ALL', 0, 0, 1, 0, 1, 1),
  (6, 2, '伊比利豬梅花', '頸肩帶油花的部位，久涮也不柴，小朋友咬得動。', 320, NULL, 0, 1, 0, 'CHILD', 0, 0, 0, 0, 2, 1),
  (7, 2, '紐西蘭小羔羊肩', '無騷味，附自製薄荷沾醬。', 340, NULL, 0, 1, 0, 'ALL', 0, 0, 0, 1, 3, 1),
  (8, 2, '台灣松阪豬', '一頭豬只有兩片的部位，脆度來自筋膜，涮 15 秒剛好。', 300, NULL, 0, 1, 0, 'ALL', 0, 0, 0, 0, 4, 1),
  (9, 2, '美國老饕牛小排', '帶筋的牛小排，口感紮實。', 520, NULL, 0, 1, 0, 'ALL', 0, 0, 1, 0, 5, 1),
  (10, 2, '霜降牛舌', '切薄片快涮，口感脆彈。', 460, NULL, 0, 1, 0, 'ALL', 0, 0, 1, 0, 6, 0),
  (11, 2, '雪花牛肋條', '肋條油脂豐富，適合重口味湯底。', 420, NULL, 0, 1, 0, 'ALL', 0, 0, 1, 0, 7, 1),
  (12, 2, '澳洲和牛 M9', '每日限量，油花細緻。', 880, NULL, 0, 1, 0, 'ALL', 0, 0, 1, 1, 8, 1),
  (13, 2, '梅花豬薄片', '價格親民的經典豬肉片。', 260, NULL, 0, 1, 0, 'CHILD', 0, 0, 0, 0, 9, 1),
  (14, 2, '去骨雞腿肉', '去皮去骨，小朋友也好入口。', 240, NULL, 0, 1, 0, 'CHILD', 0, 0, 0, 0, 10, 1),
  (15, 2, '櫻桃鴨胸', '帶皮鴨胸切片，涮到粉紅最嫩。', 280, NULL, 0, 1, 0, 'ALL', 0, 0, 0, 0, 11, 1),
  (16, 2, '伊比利豬五花', '油花多、香氣足，適合麻辣湯底。', 340, NULL, 0, 1, 0, 'ALL', 0, 0, 0, 0, 12, 1),
  (17, 3, '極鮮海陸雙拼', '牛五花與鮮蝦、干貝的雙拼盤。', 560, NULL, 0, 1, 0, 'ALL', 0, 0, 1, 0, 1, 1),
  (18, 3, '海鮮拼盤', '蝦、蛤蜊、透抽、魚片一次吃到。', 520, NULL, 0, 1, 0, 'ALL', 0, 0, 0, 0, 2, 1),
  (19, 3, '活白蝦', '每日現撈，8 尾一份。', 360, NULL, 0, 1, 0, 'ALL', 0, 0, 0, 0, 3, 1),
  (20, 3, '北海道干貝', '生食級干貝，輕涮即可。', 380, NULL, 0, 1, 0, 'ALL', 0, 0, 0, 1, 4, 1),
  (21, 3, '鮮蚵', '產地直送，涮 30 秒。', 220, NULL, 0, 1, 0, 'ALL', 0, 0, 0, 0, 5, 1),
  (22, 3, '透抽', '切圈處理，脆口。', 240, NULL, 0, 1, 0, 'ALL', 0, 0, 0, 0, 6, 1),
  (23, 3, '鯛魚片', '無刺魚片，小朋友也能吃。', 200, NULL, 0, 1, 0, 'CHILD', 0, 0, 0, 0, 7, 1),
  (24, 3, '蛤蜊', '吐沙處理過，加進湯底更鮮。', 180, NULL, 0, 1, 0, 'ALL', 0, 0, 0, 0, 8, 1),
  (25, 3, '鮭魚片', '厚切鮭魚，涮到半熟最好吃。', 300, NULL, 0, 1, 0, 'ALL', 0, 0, 0, 0, 9, 1),
  (26, 4, '時蔬八品', '當季蔬菜八種，份量適合 2–3 人。', 220, NULL, 0, 1, 0, 'ALL', 0, 1, 0, 0, 1, 1),
  (27, 4, '高麗菜', '高山高麗菜，甜度高。', 160, NULL, 0, 1, 0, 'ALL', 0, 1, 0, 0, 2, 1),
  (28, 4, '茼蒿', '火鍋必備，香氣足。', 120, NULL, 0, 1, 0, 'ALL', 0, 1, 0, 0, 3, 1),
  (29, 4, '金針菇', NULL, 100, NULL, 0, 1, 0, 'ALL', 0, 1, 0, 0, 4, 1),
  (30, 4, '杏鮑菇', NULL, 100, NULL, 0, 1, 0, 'ALL', 0, 1, 0, 0, 5, 1),
