  (32, 4, '芋頭', '大甲芋頭，煮久更綿。', 110, NULL, 0, 1, 0, 'ALL', 0, 1, 0, 0, 7, 1),
  (33, 4, '凍豆腐', '吸飽湯汁最好吃。', 80, NULL, 0, 1, 0, 'ALL', 0, 1, 0, 0, 8, 1),
  (34, 4, '菠菜', NULL, 120, NULL, 0, 1, 0, 'ALL', 0, 1, 0, 0, 9, 1),
