  (36, 5, '手工丸子', '豬肉丸、香菇丸、貢丸綜合。', 160, NULL, 0, 1, 0, 'ALL', 0, 0, 0, 0, 1, 1),
  (37, 5, '蛋餃', NULL, 120, NULL, 0, 1, 0, 'CHILD', 0, 0, 0, 0, 2, 1),
